{"code":"def transform(grid):
    # Count 4-connected nonzero components; represent each by a 4 in a six-cell row.
    h=len(grid); w=len(grid[0]) if h else 0
    seen=set(); n=0
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                n+=1; stack=[(r,c)]; seen.add((r,c))
                while stack:
                    x,y=stack.pop()
                    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
    return [[4]*min(n,6)+[0]*(6-min(n,6))]"}

